def validate(text, proof):
    # Bind the full reviewed source/REL/final-code/pointer proof, not just a flag.
    encoded=json.dumps(proof,sort_keys=True,separators=(',',':')).encode()
    if hashlib.sha256(encoded).hexdigest()!=PROOF_SHA:
        raise RuntimeError('exact current290 clone source/object/final proof mismatch')
    rows=[]
    for line in text.splitlines():
        words=line.strip().split(None,1)
        if not (len(words)==2 and words[0] in ('U','w','v')):
            raise RuntimeError('production Rust nm row format')
        rows.append(words[1])
    if not rows or rows.count('clone_thread')!=0:
        raise RuntimeError('production Rust current-profile defined provider witness')
    forbidden=[name for name in rows if 'panic_bounds_check' in name or 'unwrap_failed' in name]
    if forbidden:
        raise RuntimeError('unsupported production Rust core panic references: '+repr(forbidden))
    if sorted(rows)!=EXPECTED_PROVIDERS:
        raise RuntimeError('all other current-profile provider witnesses must remain exact')
    return {'status':'PASS_PRODUCTION_RUST_NO_TARGETED_CORE_PANIC_REFS',
            'undefined_count':len(rows),'clone_thread_undefined':0,'forbidden':forbidden,
            'clone_thread_witness':'EXACT_CURRENT290_SOURCE_REL_FINAL_TWO_R64_PROOF',
            'profile_proof_canonical_sha256':PROOF_SHA}
